fn count_under_or_over(cutoff: Int, vec: Vec<Int>) -> (Int, Int) {
    let mut below = 0;
    let mut above = 0;
    for &x in vec.iter() {
        if x <= cutoff {
            below += 1;
        } else {
            above += 1;
        }
    }
    (below, above)
}

